// expr
func (p *parser) e1() (*Node, bool) {
	return p.call(rules[1], 0)
}

// e:expr
func (p *parser) e2() (*Node, bool) {
	v, ok := p.e1()
	if ok {
		p.setCapture(0, v)
	}
	return nil, ok
}

// ws
func (p *parser) e3() (*Node, bool) {
	return p.r4()
}

// $$
func (p *parser) e4() (*Node, bool) {
	return p.anchor(p.atEnd(), idEndInput)
}

// e:expr ws $$
func (p *parser) e5() (*Node, bool) {
	if _, ok := p.e2(); !ok {
		return nil, false
	}
	if _, ok := p.e3(); !ok {
		return nil, false
	}
	if _, ok := p.e4(); !ok {
		return nil, false
	}
	return nil, true
}

// (?0-9)+
func (p *parser) e6() (*Node, bool) {
	count := 0
	for {
		ch, size, ok := p.peek()
		if !ok || !(ch >= 48 && ch <= 57) {
			p.expect(p.pos, 5)
			break
		}
		p.pos += size
		count++
	}
	return nil, count >= 1
}

