func (p *parser) r2() (*Node, bool) {
	start, rec, trail := p.pos, len(p.recovered), len(p.trail)
	prevEnv, prevCut := p.env, p.cut
	p.cut = false
	p.depth++
	if p.depth > maxDepth {
		p.tooDeep()
	}
	v, ok := p.e12()
	p.depth--
	p.cut = prevCut
	p.trail = p.trail[:trail]
	if ok {
		v = p.finish(rules[2], emptyFrame, v, start)
	} else {
		p.pos = start
		p.recovered = p.recovered[:rec]
	}
	p.env = prevEnv
	return v, ok
}

